--[[

  ONETAP UI - Custom HUD Overlay for Neverlose (CSGO)

  @author      .rifk / rifk7s
  @platform    Neverlose (CSGO)
  @repository  https://github.com/rifk7s/neverlose_csgo

  A custom Onetap-inspired HUD overlay that renders active keybinds and
  spectator information on-screen. Supports two display modes:
    * "Normale"       - all elements shown with default settings
    * "Customizable"  - individually toggle keybinds, spectators, and the gradient divider line

  Neverlose API Documentation:
    https://docs-csgo.neverlose.cc

  API modules referenced:
    ui       https://docs-csgo.neverlose.cc/documentation/variables/ui
    render   https://docs-csgo.neverlose.cc/documentation/variables/render
    entity   https://docs-csgo.neverlose.cc/documentation/variables/entity
    events   https://docs-csgo.neverlose.cc/documentation/variables/events
    globals  https://docs-csgo.neverlose.cc/documentation/variables/globals
    color    https://docs-csgo.neverlose.cc/documentation/variables/color
    vector   https://docs-csgo.neverlose.cc/documentation/variables/vector

]]

--[[

  SECTION: Sidebar & Menu Registration.
  Registers the script's sidebar tab inside the Neverlose menu.

  @see ui#sidebar
       https://docs-csgo.neverlose.cc/documentation/variables/ui#sidebar

  @ref /Neverlose CSGO Lua API
]]

ui.sidebar("OT Interface", "expand")

--[[

  SECTION: Menu Elements (UI Controls).
  All user-configurable options live under the "Main > Customization" tab.
  These controls are created using the Neverlose UI API.

  @see ui#create
       https://docs-csgo.neverlose.cc/documentation/variables/ui#create
  @see MenuGroup#switch
       https://docs-csgo.neverlose.cc/documentation/variables/ui#switch
  @see MenuGroup#combo
       https://docs-csgo.neverlose.cc/documentation/variables/ui#combo

  @ref /Neverlose CSGO Lua API
]]

local main = ui.create("Main", "Customization")

local enable_ui         = main:switch("Enable UI")                        
local mode              = main:combo("Mode", {"Normale", "Customizable"}) 
local enable_keybinds   = main:switch("Enable Keybinds")                  
local enable_spectators = main:switch("Enable Spectators")
local enable_watermark  = main:switch("Enable Watermark")
local watermark_username = main:input("Watermark Username")
local enable_line       = main:switch("Enable Line")                      
local enable_warnings   = main:switch("Enable Warnings")                   
local warnings_select   = main:selectable("Warning Types", {"velocity", "defensive"})
local warnings_color    = main:color_picker("Warning Color", color(255, 255, 255, 255))

local visuals_menu      = ui.create("Main", "Onetap Visuals")
local enable_dm         = visuals_menu:switch("Enable Damage Marker")
local dm_style          = visuals_menu:combo("Hitmarker Style", {"Onetap Default", "Signal Hitmarkers"})
local dm_options        = visuals_menu:selectable("Damage Marker Options", {"Damage", "Hitmarker"})

local signal_impacts = visuals_menu:selectable("Signal Features", {"3D hitmarker", "3D hitmarker (ragebot)", "3D damage indicator", "2D hitmarker"})
local signal_color_3d = visuals_menu:color_picker("3D Hitmarker Color", color(255, 255, 255, 255)):tooltip("Cross that stays at the exact position the enemy was hit")
local signal_color_3d_rage = visuals_menu:color_picker("3D Hitmarker Color (Ragebot)", color(255, 255, 255, 255)):tooltip("Cross that appears exactly where the aimbot fired")
local signal_color_damage = visuals_menu:color_picker("3D Damage Color", color(255, 255, 255, 255)):tooltip("Floating damage numbers showing damage dealt")
local signal_color_2d = visuals_menu:color_picker("2D Hitmarker Color", color(255, 255, 255, 255)):tooltip("Standard hitmarker drawn in the center of your screen")

local hit_font = render.load_font("Verdana", 20, "a")
local hit_markers = {}
--[[

  SECTION: Rendering Resources.
  Screen dimensions, fonts, and SVG icon assets used for on-screen rendering.



  @ref /Neverlose CSGO Lua API
]]

local screen = render.screen_size()
local font   = render.load_font("Verdana", 16, "ad")      -- HUD font: Verdana 16px, anti-aliased + drop shadow

