--[[

  SECTION: Element Visibility Controller

  Controls which menu elements are visible based on the current mode.
  In "Normale" mode, all sub-toggles are hidden since everything is shown.
  In "Customizable" mode, the individual toggles become accessible.

  @see MenuItem#visibility
       https://docs-csgo.neverlose.cc/documentation/variables/ui#visibility
  @see MenuItem#get
       https://docs-csgo.neverlose.cc/documentation/variables/ui#get
  @see events#set
       https://docs-csgo.neverlose.cc/documentation/variables/events#set

  @ref /Neverlose CSGO Lua API
]]

events.player_hurt:set(function(e)
    if not (enable_dm:get() and dm_style:get() == "Onetap Default") then return end

    local lp = entity.get_local_player()
    if not lp then return end

    if entity.get(e.attacker, true) ~= lp then return end

    local victim = entity.get(e.userid, true)
    if not victim then return end

    local hitbox = e.hitgroup == 1 and 0 or 3
    local pos = victim:get_hitbox_position(hitbox)
    
    table.insert(hit_markers, {
        pos = vector(pos.x, pos.y, pos.z),
        damage = e.dmg_health,
        is_headshot = e.hitgroup == 1,
        time = globals.realtime,
        alpha = 255
    })
end)

element_visibility = function()
    mode:visibility(enable_ui:get())
    local is_ui = enable_ui:get()
    local is_custom = mode:get() == "Customizable" and is_ui
    enable_keybinds:visibility(is_custom)
    enable_spectators:visibility(is_custom)
    enable_watermark:visibility(is_custom)
    watermark_username:visibility(is_custom and enable_watermark:get())
    enable_line:visibility(is_custom)
    enable_warnings:visibility(is_ui)
    warnings_select:visibility(is_ui and enable_warnings:get())
    warnings_color:visibility(is_ui and enable_warnings:get())
    local is_dm = enable_dm:get()
    local is_onetap = dm_style:get() == "Onetap Default"
    local is_signal = dm_style:get() == "Signal Hitmarkers"
    
    dm_style:visibility(is_dm)
    dm_options:visibility(is_dm and is_onetap)
    
    signal_impacts:visibility(is_dm and is_signal)
    signal_color_3d:visibility(is_dm and is_signal and signal_impacts:get("3D hitmarker"))
    signal_color_3d_rage:visibility(is_dm and is_signal and signal_impacts:get("3D hitmarker (ragebot)"))
    signal_color_damage:visibility(is_dm and is_signal and signal_impacts:get("3D damage indicator"))
    signal_color_2d:visibility(is_dm and is_signal and signal_impacts:get("2D hitmarker"))
end

events.render:set(element_visibility)

--[[

  SECTION: Main Render Function

  Core rendering logic executed every frame. Draws three components:
    1. Keybinds panel   - active binds displayed below screen center
    2. Spectators panel - spectating players displayed above screen center
    3. Gradient divider - visual separator between the two panels









  @ref /Neverlose CSGO Lua API
]]

--[[

  SECTION: Warning Indicator Systems.
  Ported from metaset — shows velocity slow % and defensive tickbase status.

  @see entity#m_flVelocityModifier
  @see entity#m_flSimulationTime
  @see render#rect   https://docs-csgo.neverlose.cc/documentation/variables/render#rect
  @see render#text   https://docs-csgo.neverlose.cc/documentation/variables/render#text

  @ref /Neverlose CSGO Lua API

]]

-- Smooth interpolation helper (frametime-based lerp)
local function warn_lerp(start_val, end_val, speed)
    if start_val == end_val then return end_val end
    local frametime = globals.frametime * 170
    local t = speed * frametime
    local val = start_val + (end_val - start_val) * t
    if math.abs(val - end_val) < 0.01 then return end_val end
    return val
end

-- Defensive detection system (tracks sim_time rollback per player)
local defensive = {
    db = {},
    is_active = function(self, player)
        if player == nil or not player then return {tick = 0, active = false} end

        local idx = player:get_index()
        local tickcount = globals.tickcount
        local sim_time = to_ticks(player.m_flSimulationTime or 0)

        self.db[idx] = self.db[idx] or {last_sim_time = 0, defensive_until = 0}

        if self.db[idx].last_sim_time == 0 then
            self.db[idx].last_sim_time = sim_time
            return {tick = 0, active = false}
        end

        local sim_diff = sim_time - self.db[idx].last_sim_time

        if sim_diff < 0 then
            self.db[idx].defensive_until = tickcount + math.abs(sim_diff)
        end

        self.db[idx].last_sim_time = sim_time

        return {
            tick = self.db[idx].defensive_until or 0,
            active = self.db[idx].defensive_until and (self.db[idx].defensive_until > tickcount) or false,
        }
    end
}

-- Warning font (smaller than the HUD font)
local warn_font = render.load_font("Verdana", 11, "a")

-- Velocity warning state
local vel_warn = {
    anim = {appearing = 0, appearing_alpha = 0},
    handle = function(self)
        local use_warnings = enable_warnings:get()
        local show_velocity = warnings_select:get("velocity")
        local clr = warnings_color:get()

        if not use_warnings or not show_velocity then return end

        local lplr = entity.get_local_player()
        if not lplr or not lplr:is_alive() then return end

        local modifier = lplr.m_flVelocityModifier
        local frametime = globals.frametime
        local menuopen = ui.get_alpha() > 0.5

        self.anim.appearing = warn_lerp(self.anim.appearing, (modifier < 1 or menuopen) and 230 or 180, 0.06 + math.min(frametime / 10.1, 0.25))
        self.anim.appearing_alpha = warn_lerp(self.anim.appearing_alpha, (modifier < 1 or menuopen) and 255 or 0, 0.06 + math.min(frametime / 10.1, 0.25))

        render.rect(vector(screen.x / 2 - 60, math.floor(self.anim.appearing)), vector(screen.x / 2 - 60, math.floor(self.anim.appearing)) + vector(120, 6), color(0, 0, 0, math.min(math.floor(self.anim.appearing_alpha), 200)))
        render.rect(vector(screen.x / 2 - 58, math.floor(self.anim.appearing + 2)), vector(screen.x / 2 - 58, math.floor(self.anim.appearing + 2)) + vector(116 * modifier, 2), color(clr.r, clr.g, clr.b, math.floor(self.anim.appearing_alpha)))

        render.text(warn_font, vector(screen.x / 2, math.floor(self.anim.appearing) - 7), color(255, 255, 255, math.floor(self.anim.appearing_alpha)), "c", string.format("- slow: %i%s -", math.abs(modifier * 100 + 100 * -1), "%%"))
    end
}

-- Defensive warning state
local def_warn = {
    anim = {appearing_alpha = 0},
    handle = function(self)
        local use_warnings = enable_warnings:get()
        local show_defensive = warnings_select:get("defensive")
        local clr = warnings_color:get()

        if not use_warnings or not show_defensive then return end

        local lplr = entity.get_local_player()
        if not lplr or not lplr:is_alive() then return end

        local frametime = globals.frametime
        local menuopen = ui.get_alpha() > 0.1
        local defensivetable = defensive:is_active(lplr)
        local is_defe = defensivetable.tick - globals.tickcount > 1

        self.anim.appearing_alpha = warn_lerp(self.anim.appearing_alpha, (is_defe or menuopen) and 255 or 0, 0.06 + math.min(frametime / 10.1, 0.25))

        render.rect(vector(screen.x / 2 - 60, 249), vector(screen.x / 2 - 60, 249) + vector(120, 6), color(0, 0, 0, math.min(math.floor(self.anim.appearing_alpha), 200)))
        render.rect(vector(screen.x / 2 - 58, 251), vector(screen.x / 2 - 58, 251) + vector(116 + (defensivetable.tick - globals.tickcount > 1 and ((defensivetable.tick - globals.tickcount) / 12) * -112 or 0), 2), color(clr.r, clr.g, clr.b, math.floor(self.anim.appearing_alpha)), 0, true)

        render.text(warn_font, vector(screen.x / 2, 249 - 7), color(255, 255, 255, math.floor(self.anim.appearing_alpha)), "c", "- defensive -")
    end
}

-- Reusable gradient function for UI elements
local function draw_gradient(x, y, w, h, right_to_left)
    local c1 = right_to_left and color(0):alpha_modulate(0) or color(0)
    local c2 = right_to_left and color(0) or color(0):alpha_modulate(0)
    render.gradient(vector(x, y), vector(x + w, y + h), c1, c2, c1, c2)
end

local function all()

    -- Guard clauses: abort rendering if conditions are not met
    if not enable_ui:get() then return end

    local shoudappear = false                   -- Tracks if any element was drawn (controls divider visibility)
    local w, h = 200, 18                        -- Panel width and row height (pixels)
    local enablement_of_keybinds   = true
    local enablement_of_spectators = true
    local enablement_of_line       = true
    local enablement_of_watermark  = true

    -- In "Customizable" mode, read individual toggle states from the menu
    if mode:get() == "Customizable" then
        enablement_of_keybinds   = enable_keybinds:get()
        enablement_of_spectators = enable_spectators:get()
        enablement_of_line       = enable_line:get()
        enablement_of_watermark  = enable_watermark:get()
    end

    if enablement_of_watermark then
        local custom_name = watermark_username:get()
        local username = (mode:get() == "Customizable" and custom_name and custom_name ~= "") and custom_name or (common.get_username() or "unknown")
        
        local text = string.format("onetap [debug] | %s", username)
        if globals.is_in_game then
            local net = utils.net_channel()
            if net then
                local info = net:get_server_info()
                local address = (info and info.address) or "unknown"
                local ping = 0
                if net and net.avg_latency then
                    local latency = net.avg_latency[1]
                    local updaterate = cvar.cl_updaterate:float()
                    if updaterate > 0.001 then
                        latency = latency - (0.5 / updaterate)
                    end
                    ping = math.max(0, math.floor(latency * 1000))
                end
                text = string.format("onetap [debug] | %s | %s | ping %dms", username, address, ping)
            end
        end
        local text_size = render.measure_text(font, "s", text)
        local pad_x, pad_y = 6, 4
        local bg_w = text_size.x + pad_x * 2
        local bg_h = text_size.y + pad_y * 2
        local x = screen.x - bg_w
        local y = 5
        
        -- Gradient background (transparent to translucent dark)
        render.gradient(vector(x, y), vector(x + bg_w, y + bg_h), color(0, 0, 0, 0), color(0, 0, 0, 200), color(0, 0, 0, 0), color(0, 0, 0, 200))
        
        -- Text using the same font as keybinds
        render.text(font, vector(x + pad_x, y + pad_y), color(255, 255, 255, 255), "s", text)
    end

    if not globals.is_in_game then return end
    if not entity.get_local_player() then return end
    if not entity.get_local_player():is_alive() then return end

    --[[ Keybinds Panel
         Iterates over all active keybinds, renames certain entries for a
         cleaner display, and renders each with an icon + label.
         @see ui#get_binds   https://docs-csgo.neverlose.cc/documentation/variables/ui#get_binds
         @see render#texture https://docs-csgo.neverlose.cc/documentation/variables/render#texture
         @see render#text    https://docs-csgo.neverlose.cc/documentation/variables/render#text
         @ref /Neverlose CSGO Lua API
    ]]
    
    if enablement_of_keybinds then
        local binds = ui.get_binds()
        for i = 1, #binds do
            local bind = binds[i]

            -- Rename keybind labels for a more polished display
            local c_name = binds[i].name
            if c_name == 'Peek Assist'  then c_name = 'Auto Peek'       end
            if c_name == 'Edge Jump'    then c_name = 'Jump At edge'    end
            if c_name == 'Hide Shots'   then c_name = 'Hide Shots'      end
            if c_name == 'Min. Damage'  then c_name = 'Minimum Damage'  end
            if c_name == 'Fake Latency' then c_name = 'Ping spike'      end
            if c_name == 'Fake Duck'    then c_name = 'Fake Ducking'    end
            if c_name == 'Safe Points'  then c_name = 'Safe Point'      end
            if c_name == 'Body Aim'     then c_name = 'Body Aim'        end
            if c_name == 'Double Tap'   then c_name = 'Doubletap'       end
            if c_name == 'Yaw Base'     then c_name = 'Manual Override' end
            if c_name == 'Slow Walk'    then c_name = 'Slow Motion'     end

            shoudappear = true
            local bind_icon = (bind.mode == 1) and hold_icon or enabled_icon
            local y_offset = 6
            render.texture(bind_icon, vector(6, screen.y /2 + y_offset + h/2 + (i-1)*18), color(255))
            render.text(font, vector(31, screen.y /2 + 3 + h/2 + (i-1)*18), color(255), 's', c_name)
        end
    end

    --[[ Spectators Panel
         Displays names of players currently spectating the local player.
         Rendered above the center line (negative Y offset).
         @see entity#get_spectators https://docs-csgo.neverlose.cc/documentation/variables/entity#get_spectators
         @see entity#get_name       https://docs-csgo.neverlose.cc/documentation/variables/entity#get_name
         @see render#texture        https://docs-csgo.neverlose.cc/documentation/variables/render#texture
         @see render#text           https://docs-csgo.neverlose.cc/documentation/variables/render#text
         @ref /Neverlose CSGO Lua API
    ]]

    local y_minus = 21
    if not enablement_of_line then
        y_minus = 0
    end
    if enablement_of_spectators then
        local spectators = entity.get_local_player():get_spectators()
        -- local spectators = {
        --     {name = "I"},
        --     {name = "Love"},
        --     {name = "You"},
        --     {name = "Zabolotny"},
        --     {name = "<3"},
        -- }
        for k,v in pairs(spectators) do
            shoudappear = true
            -- print_dev("im getting speced")
            render.texture(spectator_image, vector(6, screen.y /2 - y_minus - h/2 - (k-1)*18), color(255))
            render.text(font, vector(31, screen.y /2 - y_minus - h/2 - (k-1)*18), color(255), 's', v:get_name())
            -- render.text(font, vector(31, screen.y /2 - y_minus - h/2 - (k-1)*18), color(255), 's', v.name)
            y_minus = y_minus + 2.5
        end
    end

    --[[ Gradient Divider Line
         Draws a horizontal gradient bar at the vertical center of the screen
         to visually separate keybinds (below) from spectators (above).
         Only renders if at least one element was drawn.
         @see render#gradient https://docs-csgo.neverlose.cc/documentation/variables/render#gradient
         @ref /Neverlose CSGO Lua API
    ]]

    if enablement_of_line then
        if shoudappear then
            draw_gradient(0, screen.y/2 - h/2, w, h, false)
        end
    end

    --[[ Warning Indicators
         Velocity slow bar and defensive tickbase indicator.
         Rendered near the top-center of the screen with smooth fade animations.
         @ref /Neverlose CSGO Lua API
    ]]
    if enable_dm:get() and dm_style:get() == "Onetap Default" then
        local show_dmg = dm_options:get("Damage")
        local show_hit = dm_options:get("Hitmarker")
        local current_time = globals.realtime
        
        for i = #hit_markers, 1, -1 do
            local marker = hit_markers[i]
            local time_elapsed = current_time - marker.time
            
            if time_elapsed > 3.5 then
                table.remove(hit_markers, i)
            else
                if time_elapsed > 2.5 then
                    marker.alpha = marker.alpha + (0 - marker.alpha) * 0.1
                end
                if marker.alpha > 0 then
                    local screen_pos = render.world_to_screen(marker.pos)
                    if not screen_pos then goto continue end
                    
                    if show_hit then
                        local gap = 3
                        local length = 4
                        local alpha = math.floor(marker.alpha)
                        local clr = color(255, 255, 255, alpha)
                        
                        local function d_line(p1, p2)
                            -- 2px thick main line, no shadow
                            render.line(p1, p2, clr)
                            render.line(p1 + vector(1, 0), p2 + vector(1, 0), clr)
                        end
                        
                        d_line(screen_pos + vector(-gap-length, -gap-length), screen_pos + vector(-gap, -gap))
                        d_line(screen_pos + vector(gap+length, -gap-length), screen_pos + vector(gap, -gap))
                        d_line(screen_pos + vector(-gap-length, gap+length), screen_pos + vector(-gap, gap))
                        d_line(screen_pos + vector(gap+length, gap+length), screen_pos + vector(gap, gap))
                    end
                    
                    local draw_dmg = show_dmg
                    local display_damage = marker.damage
                    
                    if draw_dmg then
                        -- Prevent overlapping: if a newer hit happened recently nearby, hide this older text
                        for j = i + 1, #hit_markers do
                            local newer = hit_markers[j]
                            if (newer.pos - marker.pos):length() < 50 and (newer.time - marker.time) < 0.5 then
                                draw_dmg = false
                                break
                            end
                        end
                        
                        if draw_dmg then

                            
                            local alpha = math.floor(marker.alpha)
                            local text_color = marker.is_headshot and color(255, 50, 50, alpha) or color(255, 255, 255, alpha)
                            local text_pos = screen_pos + vector(0, -20)
                            local txt = tostring(display_damage)
                            
                            render.text(hit_font, text_pos, text_color, "c", txt)
                        end
                    end
                end
                ::continue::
            end
        end
    end

    vel_warn:handle()
    def_warn:handle()

end

events.render:set(all)-- =========================================================================
-- SIGNAL HITMARKERS (Ported from Primordial)
-- =========================================================================

local signal_damage_font = render.load_font("Segoe UI Black", 12, "a")

local hitgroup_to_hitboxes = {
    [1] = { 0, 1 },          -- HEAD -> Head, Neck
    [2] = { 4, 5, 6 },       -- CHEST -> Thorax, Chest, Upper Chest
    [3] = { 2, 3 },          -- STOMACH -> Pelvis, Body
    [4] = { 17, 18, 14 },    -- LEFT_ARM -> Left Upper Arm, Left Forearm, Left Hand
    [5] = { 15, 16, 13 },    -- RIGHT_ARM -> Right Upper Arm, Right Forearm, Right Hand
    [6] = { 8, 10, 12 },     -- LEFT_LEG -> Left Thigh, Left Calf, Left Foot
    [7] = { 7, 9, 11 }       -- RIGHT_LEG -> Right Thigh, Right Calf, Right Foot
}

local impacts = {}
local pending_impacts = {}
local last_impact_tick = 0
local screen_marker_weight = 0

local function clamp(value, minimum, maximum)
    return math.min(math.max(value, minimum), maximum)
end

local function update_weight(weight, active, duration)
    local direction = active and 1 or -1
    return clamp(weight + direction * globals.frametime / duration, 0, 1)
end

local function eased(weight)
    return weight * weight * weight
end

local function add_impact(position, duration, damage, impact_type)
    table.insert(impacts, 1, {
        position = position,
        duration = duration,
        damage = damage or 0,
        type = impact_type or "default",
        begin_weight = 0,
        roundup_weight = 0,
        life_weight = 1
    })
end

local function update_impact(impact)
    impact.life_weight = update_weight(impact.life_weight, false, impact.duration)
    impact.roundup_weight = update_weight(impact.roundup_weight, true, 0.5)
    impact.begin_weight = update_weight(
        impact.begin_weight,
        impact.life_weight > 0,
        0.1
    )
end

local function draw_cross(position, outer_offset, inner_offset, col, alpha_mult)
    local x, y = position.x, position.y
    local final_col = color(col.r, col.g, col.b, math.floor(col.a * alpha_mult))

    render.line(vector(x - outer_offset, y - outer_offset), vector(x - inner_offset, y - inner_offset), final_col)
    render.line(vector(x - outer_offset, y + outer_offset), vector(x - inner_offset, y + inner_offset), final_col)
    render.line(vector(x + inner_offset, y - inner_offset), vector(x + outer_offset, y - outer_offset), final_col)
    render.line(vector(x + inner_offset, y + inner_offset), vector(x + outer_offset, y + outer_offset), final_col)
end

local function draw_centered_damage(text, position, col, alpha_mult)
    local text_size = render.measure_text(signal_damage_font, "", text)
    local draw_position = vector(position.x, position.y - text_size.y / 2)
    local shadow_alpha = math.floor(125 * (col.a / 255) * alpha_mult)
    local final_col = color(col.r, col.g, col.b, math.floor(col.a * alpha_mult))

    render.text(signal_damage_font, vector(draw_position.x, draw_position.y + 1), color(25, 25, 25, shadow_alpha), "c", text)
    render.text(signal_damage_font, draw_position, final_col, "c", text)
end

local function get_damage_color()
    return signal_color_damage:get()
end

local function render_screen_hitmarker()
    if not signal_impacts:get("2D hitmarker") then return end

    local alpha = eased(screen_marker_weight)
    if alpha <= 0 then return end

    local position = vector(screen.x / 2, screen.y / 2)
    local outer_offset = 10 + alpha * 10
    local inner_offset = 5 + alpha * 10

    draw_cross(position, outer_offset, inner_offset, signal_color_2d:get(), alpha)
end

local function update_impacts()
    for index = #impacts, 1, -1 do
        local impact = impacts[index]
        update_impact(impact)

        if impact.life_weight == 0 and impact.begin_weight == 0 then
            table.remove(impacts, index)
        end
    end
end

local function render_impacts()
    local show_world = signal_impacts:get("3D hitmarker")
    local show_rage = signal_impacts:get("3D hitmarker (ragebot)")
    local show_damage = signal_impacts:get("3D damage indicator")

    if not show_world and not show_rage and not show_damage then return end

    local world_color = signal_color_3d:get()
    local rage_color = signal_color_3d_rage:get()
    local current_damage_color = get_damage_color()
    local current_time = globals.curtime

    for index, impact in ipairs(impacts) do
        local should_draw = (impact.type == "default" and (show_world or show_damage))
            or (impact.type == "ragebot" and show_rage)

        if should_draw then
            local screen_position = render.world_to_screen(impact.position)

            if screen_position ~= nil then
                local time_left = eased(impact.life_weight)
                local alpha = time_left * eased(impact.begin_weight)

                if alpha > 0 then
                    if impact.type == "default" then
                        if show_world then
                            draw_cross(screen_position, 10, 5, world_color, alpha)
                        end

                        if show_damage then
                            local damage = math.floor(impact.damage * eased(impact.roundup_weight))
                            local damage_position = vector(
                                screen_position.x + math.cos(current_time * 2 + index - 1) * 5,
                                screen_position.y - 25 - (1 - time_left) * 50
                            )

                            draw_centered_damage(tostring(damage), damage_position, current_damage_color, alpha)
                        end
                    elseif impact.type == "ragebot" then
                        draw_cross(screen_position, 8, 4, rage_color, alpha)
                    end
                end
            end
        end
    end
end

local function signal_on_paint()
    if not (enable_dm:get() and dm_style:get() == "Signal Hitmarkers") then return end
    
    render_screen_hitmarker()
    update_impacts()
    render_impacts()

    screen_marker_weight = update_weight(screen_marker_weight, false, 3.5)
end
events.render:set(signal_on_paint)

local function signal_on_bullet_impact(event)
    if not (enable_dm:get() and dm_style:get() == "Signal Hitmarkers") then return end
    
    local local_player = entity.get_local_player()
    local shooter = entity.get(event.userid, true)

    if local_player == nil or shooter ~= local_player then return end

    local tick = globals.tickcount
    if tick ~= last_impact_tick then
        last_impact_tick = tick
        pending_impacts = {}
    end

    table.insert(pending_impacts, vector(event.x, event.y, event.z))
end
events.bullet_impact:set(signal_on_bullet_impact)

local function signal_on_player_hurt(event)
    if not (enable_dm:get() and dm_style:get() == "Signal Hitmarkers") then return end
    
    local local_player = entity.get_local_player()
    local attacker = entity.get(event.attacker, true)
    local victim = entity.get(event.userid, true)

    if local_player == nil or attacker ~= local_player or victim == local_player then return end

    screen_marker_weight = 1

    if victim == nil or #pending_impacts == 0 then return end

    local hitboxes = hitgroup_to_hitboxes[event.hitgroup]
    if hitboxes == nil then return end

    local closest_position = nil
    local closest_distance = 8192

    for _, hitbox in ipairs(hitboxes) do
        local hitbox_position = victim:get_hitbox_position(hitbox)

        if hitbox_position ~= nil then
            for _, impact_position in ipairs(pending_impacts) do
                local distance = hitbox_position:dist(impact_position)

                if distance < closest_distance then
                    closest_distance = distance
                    closest_position = impact_position
                end
            end
        end
    end

    if closest_position ~= nil then
        add_impact(closest_position, 10, event.dmg_health, "default")
    end
end
events.player_hurt:set(signal_on_player_hurt)

local function signal_on_aimbot_shoot(shot)
    if not (enable_dm:get() and dm_style:get() == "Signal Hitmarkers") then return end
    
    if shot.target == nil then return end

    local position = nil
    if shot.x and shot.y and shot.z then
        position = vector(shot.x, shot.y, shot.z)
    elseif shot.hitbox ~= nil then
        position = shot.target:get_hitbox_position(shot.hitbox)
    elseif shot.hitgroup ~= nil then
        local hitboxes = hitgroup_to_hitboxes[shot.hitgroup]
        if hitboxes and #hitboxes > 0 then
            position = shot.target:get_hitbox_position(hitboxes[1])
        end
    end

    if position ~= nil then
        add_impact(position, 5, 0, "ragebot")
    end
end
events.aim_fire:set(signal_on_aimbot_shoot)
